CREATE DATABASE IF NOT EXISTS kjc_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kjc_portal;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','STUDENT') DEFAULT 'STUDENT',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,student_id VARCHAR(50) UNIQUE NOT NULL,course VARCHAR(120) NOT NULL,semester VARCHAR(60) NOT NULL,phone VARCHAR(30) DEFAULT '',address VARCHAR(255) DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,subject VARCHAR(120) NOT NULL,attended INT DEFAULT 0,total INT DEFAULT 0,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS marks(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,subject VARCHAR(120) NOT NULL,internal DECIMAL(6,2) DEFAULT 0,assignment DECIMAL(6,2) DEFAULT 0,exam DECIMAL(6,2) DEFAULT 0,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS assignments(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,title VARCHAR(180) NOT NULL,subject VARCHAR(120) NOT NULL,due_date DATE NOT NULL,status ENUM('Pending','Submitted','Late') DEFAULT 'Pending',submitted_at DATETIME NULL,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS timetable(id INT AUTO_INCREMENT PRIMARY KEY,course VARCHAR(120) NOT NULL,semester VARCHAR(60) NOT NULL,day_name VARCHAR(20) NOT NULL,period_time VARCHAR(40) NOT NULL,subject VARCHAR(120) NOT NULL,room VARCHAR(40) DEFAULT '');
CREATE TABLE IF NOT EXISTS notifications(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS leave_requests(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,from_date DATE NOT NULL,to_date DATE NOT NULL,reason TEXT NOT NULL,status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fees(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,semester VARCHAR(60) NOT NULL,amount DECIMAL(10,2) NOT NULL,paid DECIMAL(10,2) DEFAULT 0,due_date DATE NULL,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS certificates(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,title VARCHAR(180) NOT NULL,issued_on DATE NOT NULL,certificate_no VARCHAR(80) NOT NULL,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS login_history(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,ip_address VARCHAR(64),logged_in_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
